from datetime import date
import pytest
from src.windows import overlaps

def d(day): return date(2026, 1, day)

def test_shared_endpoint_overlaps(): assert overlaps(d(1), d(3), d(3), d(5))
def test_disjoint(): assert not overlaps(d(1), d(2), d(3), d(4))
def test_reversed_left_rejected():
    with pytest.raises(ValueError): overlaps(d(4), d(2), d(5), d(6))
def test_reversed_right_rejected():
    with pytest.raises(ValueError): overlaps(d(1), d(2), d(6), d(5))

