import re

def normalize_label(value: str) -> str:
    value = value.strip().lower()
    value = re.sub(r'[^a-z0-9]+', '-', value)
    return value.strip('-')

def normalize_many(values: list[str]) -> list[str]:
    result = []
    for value in values:
        value = value.strip().lower()
        value = re.sub(r'[^a-z0-9]+', '-', value)
        result.append(value.strip('-'))
    return result
